     "text": "대기는 지구를 둘러싼 공기예요. 맑고 구름이 없는 곳에도 공기가 있어요. 지구 전체 표면에서는 바다가 육지보다 넓어요. 한쪽 사진만 보거나 구름을 육지로 세어 판단하지 않아요."
